// Tiny ES-module → single classic <script> bundler for the browser code in src/js.
// Why: browsers refuse <script type="module"> on file:// pages, so a bundle lets the site
// work when index.html is simply double-clicked (and loads faster everywhere else).
import fs from 'node:fs';
import path from 'node:path';

function walk(dir, base = dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, base, out);
    else if (e.name.endsWith('.js')) out.push(path.relative(base, p).split(path.sep).join('/').replace(/\.js$/, ''));
  }
  return out;
}

function transform(id, src) {
  const exported = [];
  let def = null;
  src = src.replace(/import\s*\{([\s\S]*?)\}\s*from\s*'([^']+)';?/g, (m, names, from) => {
    const target = path.posix.join(path.posix.dirname(id), from).replace(/\.js$/, '');
    const list = names.split(',').map((s) => s.trim()).filter(Boolean).map((s) => s.replace(/\s+as\s+/, ': ')).join(', ');
    return `const { ${list} } = __require('${target}');`;
  });
  src = src.replace(/await import\(`\.\/pages\/\$\{page\}\.js`\)/g, "__require('pages/' + page)");
  src = src.replace(/^export default (async )?function (\w+)/gm, (m, a, name) => { def = name; return `${a || ''}function ${name}`; });
  src = src.replace(/^export (async )?function (\w+)/gm, (m, a, name) => { exported.push(name); return `${a || ''}function ${name}`; });
  src = src.replace(/^export (const|let) (\w+)/gm, (m, k, name) => { exported.push(name); return `${k} ${name}`; });
  if (/^\s*(import|export)\s/m.test(src.replace(/\/\/.*$/gm, ''))) throw new Error(`Unsupported import/export syntax left in module "${id}"`);
  const ex = [...exported.map((n) => n), ...(def ? [`default: ${def}`] : [])].join(', ');
  return `'${id}': function (module) {\n'use strict';\n${src}\nmodule.exports = { ${ex} };\n}`;
}

export function bundle(srcDir, entry = 'app') {
  const ids = walk(srcDir);
  const defs = ids.map((id) => transform(id, fs.readFileSync(path.join(srcDir, id + '.js'), 'utf8')));
  return `/* Gamepov browser bundle — generated by scripts/build.js, do not edit. */
(function () {
'use strict';
var __defs = {
${defs.join(',\n')}
};
var __cache = {};
function __require(id) {
  if (__cache[id]) return __cache[id].exports;
  var d = __defs[id];
  if (!d) throw new Error('Unknown module ' + id);
  var m = { exports: {} };
  __cache[id] = m;
  d(m);
  return m.exports;
}
__require('${entry}');
})();
`;
}
